function dupConfidence(a, b) {
  if (a.phone_key && a.phone_key === b.phone_key) return { score: 1.0, on: 'phone_key' };
  if (a.email_norm && a.email_norm === b.email_norm) return { score: 0.95, on: 'email_norm' };
