function materiallyConflicts(ruleBand, ai) {
  if (!ai || ai.ai_status !== 'ok') return false;
  if (Number(ai.ai_confidence) < CONFLICT.MIN_CONFIDENCE) return false;
  const aiBand = AI_IMPLIED_BAND[ai.ai_intent];
